import { tags } from "typia";

/**
 * Summary statistics about tasks across the platform. Counts exclude
 * soft-deleted tasks (deleted_at IS NOT NULL). completionRate is a fractional
 * value in the closed interval [0,1] representing (completed_tasks /
 * total_tasks). When total_tasks is 0, completionRate MUST be 0.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type ITodoAppTaskStats = {
  /**
   * Total number of tasks present across the system (exclude soft-deleted
   * tasks).
   */
  total_tasks: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Number of tasks currently marked as completed (exclude soft-deleted
   * tasks).
   */
  completed_tasks: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Fractional completion rate computed as completed_tasks / total_tasks.
   * Value is in [0,1]. When total_tasks == 0 the value MUST be 0 to avoid NaN
   * or null.
   */
  completion_rate: number & tags.Minimum<0> & tags.Maximum<1>;

  /**
   * Number of tasks with due_date within the configured 'due soon' window
   * (e.g., next 7 days). Excludes completed and soft-deleted tasks.
   */
  due_soon_count: number & tags.Type<"int32"> & tags.Minimum<0>;
};
